using namespace std;

int main() {
    int a[] = {1, 2, 3};
    int n = 3;
    for (int mask = 0; mask < (1 << n); mask++) {
        cout << "{";
        bool first = true;
        for (int i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                if (!first) cout << ", ";
                cout << a[i];
                first = false;
            }
        }
        cout << "}" << endl;
    }
    return 0;
}

