#include <iostream>
using namespace std;

int a[] = {3, 1, 4, 1, 5};
int n = 5, target = 7;
int minCnt = 999;

void dfs(int idx, int sum, int cnt) {
    if (sum > target) return;
    if (cnt >= minCnt) return;
    if (idx == n) {
        if (sum == target && cnt < minCnt) minCnt = cnt;
        return;
    }
    dfs(idx + 1, sum + a[idx], cnt + 1);
    dfs(idx + 1, sum, cnt);
}

int main() {
    dfs(0, 0, 0);
    cout << "最少选 " << minCnt << " 个" << endl;
    return 0;
}

